-- Separate boiled, roasted and fried potato densities.
update public.foods as f
set name = v.name,
    carbs_g = v.carbs_g,
    notes = v.notes,
    habitual_measure = v.habitual_measure,
    updated_at = now()
from (values
('patata-cocida', 'Patata hervida', 10, 'Murillo 3ª ed. (Fundación para la Salud / CIBERDEM) + BEDCA. ES: 10 g HC = 1 ración. HC totales. Patata hervida: 65 g = 1 ración.', '{"label":"Plato mediano","grams":200}'::jsonb),
('patata-frita', 'Patata frita', 15, 'BEDCA f_id 883 Patata, frita con aceite: 30 g HC/100 g (carbohidratos). 50 g = 15 g HC. 3 g fibra/100 g, no se suma. Murillo 3ª ed. redondea 30 g de alimento = 1 ración (33 g/100 g).', '{"label":"Guarnición","grams":60}'::jsonb),
('es-patata-asada', 'Patata asada', 69, 'BEDCA2 f_id 2402 Patata, asada: 46 g HC/100 g (carbohidratos), agua 47 %. 150 g = 69 g HC. 7,9 g fibra/100 g, no se suma. La hervida (f_id 2404) está en 15,6 g/100 g y un 79 % de agua. Murillo 3ª ed. redondea 35 g = 1 ración; por encima del redondeo, manda BEDCA.', null::jsonb),
('patata-cocida-150g', 'Patata hervida', 23, 'Murillo 3ª ed. (Fundación para la Salud / CIBERDEM) + BEDCA. ES: 10 g HC = 1 ración. HC totales. Patata hervida 15,4 g HC/100 g → 150 g ≈ 2,3 raciones.', '{"label":"Plato mediano","grams":200}'::jsonb),
('patatas-fritas-150g', 'Patatas fritas (ración mediana)', 45, 'BEDCA f_id 883 Patata, frita con aceite: 30 g HC/100 g (carbohidratos). 150 g = 45 g HC. 3 g fibra/100 g, no se suma. Murillo 3ª ed. redondea 30 g de alimento = 1 ración (33 g/100 g).', '{"label":"Guarnición","grams":60}'::jsonb),
('patatas-fritas-100g', 'Patatas fritas (ración pequeña)', 30, 'BEDCA f_id 883 Patata, frita con aceite: 30 g HC/100 g (carbohidratos). 100 g = 30 g HC (3 raciones). 3 g fibra/100 g, no se suma. Murillo 3ª ed. redondea 30 g de alimento = 1 ración (33 g/100 g).', '{"label":"Guarnición","grams":60}'::jsonb)
) as v(id, name, carbs_g, notes, habitual_measure)
where f.id = v.id;

update public.foods
set grams = 65,
    portion_text = '1 ración (65 g hervida)'
where id = 'patata-cocida';

update public.lessons set summary = 'Carne, pollo, huevo, pescado y aceites no aportan raciones de hidratos, aunque pueden modificar la respuesta glucémica de una comida mixta.', steps = '[{"id":"l1-lesson-3-s1","type":"explanation","title":"¿Qué son los moduladores?","body":"Son alimentos con 0 o casi 0 carbohidratos: pollo, carne, huevo, pescado, aceite, mantequilla. No aportan raciones de HC. Sí pueden modificar la respuesta glucémica cuando van con carbohidratos (comida mixta)."},{"id":"l1-lesson-3-s2","type":"explanation","title":"¿Por qué importan?","body":"Las proteínas y grasas retrasan la absorción de los carbohidratos. Una pizza con mucho queso sube la glucosa más tarde que un pan solo."},{"id":"l1-lesson-3-s3","type":"example","title":"Ejemplo: tortilla española","body":"1 huevo = 0 g HC. 100 g de patata hervida = ~15 g HC (1,5 raciones). La tortilla tiene HC por la patata, no por el huevo.","foodId":"huevo"},{"id":"l1-lesson-3-s4","type":"example","title":"Regla de oro","body":"Si el alimento es solo proteína o grasa (pollo a la plancha, aceite de oliva), cuenta 0 raciones. Si tiene mezcla (empanado, salsa), lee la etiqueta.","foodId":"pollo"},{"id":"l1-lesson-3-practice","type":"practice","title":"Practica ahora","body":"Comprueba lo aprendido con un ejercicio rápido.","exerciseId":"ex-l1-3-zero-carb-identify"}]'::jsonb, updated_at = now() where id = 'l1-lesson-3';

update public.lessons set summary = 'Patata, boniato y batata cuentan como raciones, no como verduras libres. Aprende porciones y formas de cocción.', steps = '[{"id":"l2-lesson-2-s1","type":"example","title":"Patata hervida","body":"1 patata mediana hervida (150 g) = 23 g HC (2,3 raciones). El peso es el de la patata ya cocida.","foodId":"patata-cocida-150g"},{"id":"l2-lesson-2-s1a","type":"example","title":"Patata asada","body":"La misma cantidad ya asada (150 g) = 69 g HC (6,9 raciones). Al horno pierde agua y el hidrato se concentra.","foodId":"es-patata-asada"},{"id":"l2-lesson-2-s1b","type":"example","title":"Patata frita","body":"100 g de patata frita = 30 g HC (3 raciones). La grasa no se suma como hidrato.","foodId":"patatas-fritas-100g"},{"id":"l2-lesson-2-s2","type":"example","title":"Boniato/batata","body":"1 boniato pequeño (130 g) = ~26 g HC (2,6 raciones). Es más dulce que la patata pero cuenta similar.","foodId":"boniato-asado-130g"},{"id":"l2-lesson-2-s3","type":"example","title":"Puré instantáneo","body":"Cuidado: el puré de sobre puede tener leche en polvo y almidones. 100 g de puré preparado = ~12 g HC (1,2 raciones).","foodId":"es-pure-patata"},{"id":"l2-lesson-2-s4","type":"explanation","title":"Consejo de cocción","body":"Freír añade grasa, que no cuenta como hidrato pero retrasa la subida de glucosa. Asar no lleva ese aceite; lo que cambia el número es el agua que pierde."},{"id":"l2-lesson-2-practice","type":"practice","title":"Practica ahora","body":"Comprueba lo aprendido con un ejercicio rápido.","exerciseId":"ex-l2-2-potato-sweet-potato"}]'::jsonb, updated_at = now() where id = 'l2-lesson-2';

update public.lessons set summary = 'La mayoría de comidas combinan varios alimentos. Aprende a sumar las raciones de cada ingrediente para obtener el total.', steps = '[{"id":"l4-lesson-1-s1","type":"explanation","title":"Descomponer el plato","body":"Separa mentalmente cada ingrediente: pan + carne + patata + ensalada. Suma solo los que tienen carbohidratos."},{"id":"l4-lesson-1-s2","type":"example","title":"Ejemplo: filete con patatas","body":"Filete de ternera = 0 raciones (solo proteína). 150 g de patata hervida = 2,3 raciones. Ensalada = 0 raciones. Total = 2,3 raciones.","foodId":"patata-cocida-150g"},{"id":"l4-lesson-1-s3","type":"example","title":"Salsas y rebozados","body":"El rebozado (harina, pan rallado) suma carbohidratos. Las salsas con azúcar (kétchup, salsa barbacoa) también. Lee la etiqueta.","foodId":"ketchup"},{"id":"l4-lesson-1-s4","type":"example","title":"Plato del servidor","body":"Divide tu plato en 3: ½ verduras, ¼ proteína (pollo, pescado), ¼ carbohidratos (arroz, patata, pasta). Es la recomendación de la ADA y FEN.","foodId":"ensalada-mixta","sourceIds":["ada","fen"]},{"id":"l4-lesson-1-practice","type":"practice","title":"Practica ahora","body":"Comprueba lo aprendido con un ejercicio rápido.","exerciseId":"ex-l4-1-mixed-plate-sum"}]'::jsonb, updated_at = now() where id = 'l4-lesson-1';

update public.lessons set summary = 'Comer fuera es un reto. Aprende a estimar raciones en situaciones sociales: tapeo, bocadillos, comida rápida.', steps = '[{"id":"l4-lesson-3-s1","type":"example","title":"Bocadillos","body":"1 bocadillo de pan de barra (100 g de pan) = ~50 g HC (5 raciones). El relleno (jamón, tortilla) no cuenta, solo el pan.","foodId":"bocadillo-jamon"},{"id":"l4-lesson-3-s2","type":"example","title":"Tapas típicas","body":"Patatas fritas (ración mediana 150 g) = 45 g HC (4,5 raciones). Calamares a la romana (rebozados) = ~15 g HC por el rebozado.","foodId":"patatas-fritas-150g"},{"id":"l4-lesson-3-s3","type":"example","title":"Pizza (margarita / pepperoni)","body":"1 porción de pizza margarita (~150 g) = ~30 g HC (3 raciones) por la masa. La pepperoni (~125 g) ≈ 30 g HC. Cuanto más fina la masa, menos HC. El queso y la mayoría de toppings no suman. Valores educativos estándar; varían según pizzería.","foodId":"es-pizza-es"},{"id":"l4-lesson-3-s4","type":"example","title":"Truco de restaurante","body":"Pide la salsa aparte, elige opciones a la plancha, y comparte las patatas fritas o el pan. Así controlas mejor las raciones.","foodId":"calamares-romana"},{"id":"l4-lesson-3-practice","type":"practice","title":"Practica ahora","body":"Comprueba lo aprendido con un ejercicio rápido.","exerciseId":"ex-l4-3-tapas-bocadillo-pizza"}]'::jsonb, updated_at = now() where id = 'l4-lesson-3';

update public.lessons set summary = 'Integra todo lo aprendido calculando raciones en menús completos de un día. Practica con casos reales.', steps = '[{"id":"l5-lesson-2-s1","type":"example","title":"Desayuno típico","body":"1 vaso de leche (1 ración) + 2 tostadas de pan (2 raciones) + 1 pieza de fruta (1,5 raciones) = 4,5 raciones totales.","foodId":"tostadas-pan"},{"id":"l5-lesson-2-s2","type":"example","title":"Comida completa","body":"Ensalada (0) + filete con patata hervida (2,3 raciones) + 1 yogur (0,5 raciones) + 1 fruta (1 ración) = 3,8 raciones totales.","foodId":"patata-cocida-150g"},{"id":"l5-lesson-2-s3","type":"example","title":"Merienda","body":"1 sándwich pequeño (2 raciones) o 1 fruta + 3-4 nueces (0 raciones, solo grasa). Las nueces no suman HC.","foodId":"es-sandwich-mixto"},{"id":"l5-lesson-2-s4","type":"example","title":"Cena ligera","body":"Gazpacho (~1–1,5 raciones según porción del catálogo) + tortilla francesa (0 raciones de HC) + 1 rebanada de pan (1 ración) ≈ 2–2,5 raciones. Ideal para la noche.","foodId":"es-gazpacho"},{"id":"l5-lesson-2-practice","type":"practice","title":"Practica ahora","body":"Comprueba lo aprendido con un ejercicio rápido.","exerciseId":"ex-l5-2-full-day-menu"}]'::jsonb, updated_at = now() where id = 'l5-lesson-2';
